ALTER TABLE drones ADD COLUMN IF NOT EXISTS x_position INTEGER DEFAULT 100;
ALTER TABLE drones ADD COLUMN IF NOT EXISTS y_position INTEGER DEFAULT 100;
UPDATE drones SET x_position = CASE id%5 WHEN 0 THEN 80 WHEN 1 THEN 165 WHEN 2 THEN 240 WHEN 3 THEN 305 ELSE 360 END WHERE x_position IS NULL OR x_position=100;
UPDATE drones SET y_position = CASE id%4 WHEN 0 THEN 100 WHEN 1 THEN 180 WHEN 2 THEN 260 ELSE 330 END WHERE y_position IS NULL OR y_position=100;